const CACHE='huruf-v11';const FILES=['./','./index.html','./style.css','./gate.js','./app.js','./vocab.js','./learning.js','./manifest.webmanifest','./icon.svg'];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting()});self.addEventListener('activate',e=>{e.waitUntil((async()=>{const keys=await caches.keys();await Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)));await self.clients.claim()})())});self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith((async()=>{const cache=await caches.open(CACHE);try{const fresh=await fetch(e.request);if(fresh.ok)cache.put(e.request,fresh.clone());return fresh}catch{return await caches.match(e.request)||Response.error()}})())});

